def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    open_paren = lst[0].count('(')
    close_paren = lst[0].count(')')
