    close_paren += lst[1].count(')')

    if open_paren != close_paren:
        return 'No'

    perms = permutations(lst)
    for perm in perms:
        concat_str = ''.join(perm)
        if is_balanced(concat_str):
            return 'Yes'

    return 'No'

